async function clearAndExit(store, navigator, keys, destination) {
  if (store === null || typeof store !== 'object' || typeof store.remove !== 'function' ||
      navigator === null || typeof navigator !== 'object' || typeof navigator.go !== 'function' ||
      !Array.isArray(keys) || typeof destination !== 'string' || destination.length === 0 ||
      keys.some((key) => typeof key !== 'string' || key.length === 0)) {
    throw new TypeError('invalid arguments');
  }

  const uniqueKeys = Array.from(new Set(keys));
  const removed = [];
  const failed = [];

  for (const key of uniqueKeys) {
    try {
      await store.remove(key);
      removed.push(key);
    } catch (error) {
      const reason = error && typeof error.message === 'string'
        ? error.message
        : String(error);
      failed.push({ key, reason });
    }
  }

  if (failed.length === 0) await navigator.go(destination);
  return { removed, failed };
}

module.exports = { clearAndExit };

