'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepEqual(Object.keys(api), ['clearAndExit']);
const { clearAndExit } = api;

(async () => {
  let calls = 0;
  const store = { remove() { calls++; } };
  const navigator = { go() { calls++; } };
  const invalidCases = [
    [null, navigator, [], '/home'],
    [{}, navigator, [], '/home'],
    [store, null, [], '/home'],
    [store, {}, [], '/home'],
    [store, navigator, null, '/home'],
    [store, navigator, [''], '/home'],
    [store, navigator, [1], '/home'],
    [store, navigator, [], '']
  ];
  for (const args of invalidCases) await assert.rejects(clearAndExit(...args), TypeError);
  assert.equal(calls, 0);

  const keys = ['a', 'b', 'a', 'c', 'b'];
  const originalKeys = keys.slice();
  const log = [];
  let activeRemovals = 0;
  const result = await clearAndExit({
    async remove(key) {
      assert.equal(activeRemovals, 0, 'removals must be sequential');
      activeRemovals++;
      log.push('start:' + key);
      await Promise.resolve();
      activeRemovals--;
      log.push('end:' + key);
      if (key === 'b') throw new Error('cannot remove');
      if (key === 'c') throw 'plain failure';
      return key;
    }
  }, {
    go(destination) {
      log.push('go:' + destination);
      return 'navigated';
    }
  }, keys, '/done');
  assert.deepEqual(keys, originalKeys);
  assert.deepEqual(log, [
    'start:a', 'end:a',
    'start:b', 'end:b',
    'start:c', 'end:c',
    'go:/done'
  ]);
  assert.deepEqual(result, {
    removed: ['a'],
    failed: [
      { key: 'b', reason: 'cannot remove' },
      { key: 'c', reason: 'plain failure' }
    ]
  });

  let emptyNavigation = 0;
  assert.deepEqual(await clearAndExit({ remove() { throw new Error('unused'); } }, {
    go(destination) { emptyNavigation++; assert.equal(destination, '/empty'); }
  }, [], '/empty'), { removed: [], failed: [] });
  assert.equal(emptyNavigation, 1);

  const navigationFailure = new Error('navigation failed');
  let navCalls = 0;
  await assert.rejects(clearAndExit({
    remove(key) { if (key === 'x') throw new Error('remove failed'); }
  }, {
    async go() { navCalls++; throw navigationFailure; }
  }, ['x', 'y'], '/next'), error => error === navigationFailure);
  assert.equal(navCalls, 1);
})().catch(error => {
  console.error(error);
  process.exitCode = 1;
});

